{"path": "book_store.py", "content": "from collections import Counter
from functools import lru_cache
from itertools import combinations

PRICE = 800  # cents per book
DISCOUNTS = {1: 0, 2: 5, 3: 10, 4: 20, 5: 25}


def _group_price(size):
    return size * PRICE * (100 - DISCOUNTS[size]) // 100


@lru_cache(maxsize=None)
def _best(counts):
    """Minimum price (in cents) for a sorted tuple of per-title counts."""
    counts = tuple(c for c in counts if c > 0)
    if not counts:
        return 0
    best = None
    n = len(counts)
    for size in range(1, n + 1):
        for chosen in combinations(range(n), size):
            remaining = list(counts)
            for i in chosen:
                remaining[i] -= 1
            cost = _group_price(size) + _best(tuple(sorted(remaining, reverse=True)))
            if best is None or cost < best:
                best = cost
    return best


def total(basket):
    """Return the cheapest price of the basket in cents."""
    counts = sorted(Counter(basket).values(), reverse=True)
    return _best(tuple(counts))
"}

